Class Mochila
  Define dueno As String;
  Define libros As Integer;
EndClass

Algorithm Copias
  Define a As Mochila <- New Mochila();
  a.dueno <- "Ana";
  a.libros <- 3;
  Define alias As Mochila <- a;
  Define copia As Mochila <- copy(a);
  alias.libros <- 5;
  copia.libros <- 9;
  Write a.libros, " ", alias.libros, " ", copia.libros;
  Write a = alias, " ", a = copia;
EndAlgorithm
